def start_codegen_session(options, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    t0 = time.time()
    events_file = "automation_events.json"

    def _log_event(status, request_params, result=None, error=None, duration_ms=None, session_id=None, tab_id=None, codegen_session_id=None):
        try:
            events = _load(events_file)
            ts = _now()
            ev = {
                "id": "evt_" + uuid.uuid4().hex,
                "session_id": session_id,
                "tab_id": tab_id,
                "codegen_session_id": codegen_session_id,
                "tool_name": "start_codegen_session",
                "status": status,
                "request_params": request_params if isinstance(request_params, dict) else {},
                "result": result,
                "error": error,
                "duration_ms": duration_ms,
                "created_at": ts,
                "updated_at": ts,
            }
            events.append(ev)
            _save(events_file, events)
        except Exception:
            return

    # Validation
    if options is None or not isinstance(options, dict):
        dur = int((time.time() - t0) * 1000)
        _log_event("failed", {"options": options}, error={"message": "options must be an object"}, duration_ms=dur)
        return _err("VALIDATION_ERROR", "options must be an object")

    output_path = options.get("outputPath")
    test_name_prefix = options.get("testNamePrefix", "GeneratedTest")
    include_comments = options.get("includeComments", True)

    if not isinstance(output_path, str) or not output_path.strip():
        dur = int((time.time() - t0) * 1000)
        _log_event("failed", {"options": options}, error={"message": "options.outputPath is required and must be a non-empty string"}, duration_ms=dur)
        return _err("VALIDATION_ERROR", "options.outputPath is required and must be a non-empty string", field="options.outputPath")

    if not output_path.startswith("/"):
        dur = int((time.time() - t0) * 1000)
        _log_event("failed", {"options": options}, error={"message": "options.outputPath must be an absolute path starting with '/'."}, duration_ms=dur)
        return _err("VALIDATION_ERROR", "options.outputPath must be an absolute path starting with '/'.", field="options.outputPath")

    if test_name_prefix is None:
        test_name_prefix = "GeneratedTest"
    if not isinstance(test_name_prefix, str) or test_name_prefix == "":
        dur = int((time.time() - t0) * 1000)
        _log_event("failed", {"options": options}, error={"message": "options.testNamePrefix must be a non-empty string"}, duration_ms=dur)
        return _err("VALIDATION_ERROR", "options.testNamePrefix must be a non-empty string", field="options.testNamePrefix")

    if not isinstance(include_comments, bool):
        dur = int((time.time() - t0) * 1000)
        _log_event("failed", {"options": options}, error={"message": "options.includeComments must be a boolean"}, duration_ms=dur)
        return _err("VALIDATION_ERROR", "options.includeComments must be a boolean", field="options.includeComments")

    # Ambient auth: no explicit credential. Consider authorized if service is operable.
    # We keep minimal policy: always authorized.
    try:
        codegen = _load("codegen_sessions.json")
    except Exception:
        dur = int((time.time() - t0) * 1000)
        _log_event("failed", {"options": options}, error={"message": "Unable to access datastore"}, duration_ms=dur)
        return _err("UNAUTHORIZED", "Unable to access datastore")

    ts = _now()
    new_id = "cgen_" + uuid.uuid4().hex
    row = {
        "id": new_id,
        "status": "recording",
        "session_id": None,
        "output_path": output_path,
        "test_name_prefix": test_name_prefix,
        "include_comments": include_comments,
        "recorded_actions": [],
        "generated_test_file_path": None,
        "generated_source": None,
        "last_error": None,
        "created_at": ts,
        "updated_at": ts,
        "ended_at": None,
    }
    codegen.append(row)
    try:
        _save("codegen_sessions.json", codegen)
    except Exception:
        dur = int((time.time() - t0) * 1000)
        _log_event("failed", {"options": options}, error={"message": "Failed to persist codegen session"}, duration_ms=dur)
        return _err("CONFLICT", "Failed to persist codegen session")

    dur = int((time.time() - t0) * 1000)
    _log_event("succeeded", {"options": {"outputPath": output_path, "testNamePrefix": test_name_prefix, "includeComments": include_comments}}, result={"session": row}, duration_ms=dur, codegen_session_id=new_id)

    return {"session": row}

def playwright_navigate(url, browserType=None, width=None, height=None, timeout=None, waitUntil=None, headless=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string", field="url")
    if not url.strip().lower().startswith("http"):
        return _err("VALIDATION_ERROR", "url must start with 'http'", field="url")
    if browserType is not None:
        if not isinstance(browserType, str) or browserType not in ("chromium", "firefox", "webkit"):
            return _err("VALIDATION_ERROR", "browserType must be one of: chromium, firefox, webkit", field="browserType")
    def _as_int(nm, v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{nm} must be a number", field=nm)
        if isinstance(v, (int, float)):
            iv = int(v)
            if iv != v and not isinstance(v, int):
                # allow floats that are whole numbers
                pass
            return iv, None
        return None, _err("VALIDATION_ERROR", f"{nm} must be a number", field=nm)

    w, e = _as_int("width", width)
    if e: return e
    h, e = _as_int("height", height)
    if e: return e
    to_ms, e = _as_int("timeout", timeout)
    if e: return e
    if headless is not None and not isinstance(headless, bool):
        return _err("VALIDATION_ERROR", "headless must be a boolean", field="headless")

    # Range constraints
    if w is not None and not (100 <= w <= 10000):
        return _err("VALIDATION_ERROR", "width must be between 100 and 10000", field="width")
    if h is not None and not (100 <= h <= 10000):
        return _err("VALIDATION_ERROR", "height must be between 100 and 10000", field="height")
    if to_ms is not None and not (0 <= to_ms <= 600000):
        return _err("VALIDATION_ERROR", "timeout must be between 0 and 600000", field="timeout")

    # waitUntil is vendor-specific; accept common values if provided
    if waitUntil is not None:
        if not isinstance(waitUntil, str) or not waitUntil.strip():
            return _err("VALIDATION_ERROR", "waitUntil must be a non-empty string when provided", field="waitUntil")
        allowed = {"load", "domcontentloaded", "networkidle", "commit"}
        if waitUntil not in allowed:
            return _err("VALIDATION_ERROR", f"waitUntil must be one of: {', '.join(sorted(allowed))}", field="waitUntil")

    browser_sessions = _load("browser_sessions.json")
    tabs = _load("tabs.json")
    codegen_sessions = _load("codegen_sessions.json")
    automation_events = _load("automation_events.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Pick or create an active session (chosen consistent policy: implicitly create if none active)
    active_sessions = [s for s in browser_sessions if s.get("status") == "active"]
    if active_sessions:
        session = sorted(active_sessions, key=lambda r: r.get("created_at") or "")[-1]
        # Reject if somehow closed/closing/errored; should not happen due to filter
    else:
        # Create implicit session with defaults
        sid = _new_id("bs")
        session = {
            "id": sid,
            "status": "active",
            "browser_type": "chromium",
            "headless": False,
            "viewport_width": 1280,
            "viewport_height": 720,
            "default_timeout_ms": None,
            "user_agent": None,
            "current_url": None,
            "active_tab_id": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
            "closed_at": None
        }
        browser_sessions.append(session)

    # If session not active, reject (rule: subsequent tool invocations against a closed session must be rejected)
    if session.get("status") != "active":
        # log failed event
        ev_id = _new_id("ev")
        duration_ms = int((time.time() - t0) * 1000)
        automation_events.append({
            "id": ev_id,
            "session_id": session.get("id"),
            "tab_id": session.get("active_tab_id"),
            "codegen_session_id": None,
            "tool_name": "playwright_navigate",
            "status": "failed",
            "request_params": {"url": url, "browserType": browserType, "width": width, "height": height, "timeout": timeout, "waitUntil": waitUntil, "headless": headless},
            "result": None,
            "error": {"message": "Session is not active", "code": "INVALID_TRANSITION"},
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now
        })
        _save("automation_events.json", automation_events)
        _save("browser_sessions.json", browser_sessions)
        return _err("INVALID_TRANSITION", "Session is not active")

    # Apply provided session settings
    changed = False
    if browserType is not None and session.get("browser_type") != browserType:
        session["browser_type"] = browserType
        changed = True
    if headless is not None and session.get("headless") != headless:
        session["headless"] = headless
        changed = True
    if w is not None and session.get("viewport_width") != w:
        session["viewport_width"] = w
        changed = True
    if h is not None and session.get("viewport_height") != h:
        session["viewport_height"] = h
        changed = True
    if to_ms is not None and session.get("default_timeout_ms") != to_ms:
        session["default_timeout_ms"] = to_ms
        changed = True

    # Ensure there is an active tab; if none, create initial
    sid = session["id"]
    session_tabs = [t for t in tabs if t.get("session_id") == sid and t.get("status") != "closed"]
    active_tab = None
    if session.get("active_tab_id"):
        for t in tabs:
            if t.get("id") == session["active_tab_id"] and t.get("session_id") == sid and t.get("status") != "closed":
                active_tab = t
                break
    if active_tab is None:
        # find any open active, else any open, else create
        actives = [t for t in session_tabs if t.get("is_active") is True and t.get("status") == "open"]
        if actives:
            active_tab = actives[0]
            session["active_tab_id"] = active_tab["id"]
            changed = True
        else:
            opens = [t for t in session_tabs if t.get("status") == "open"]
            if opens:
                # enforce at most one is_active by activating the first and deactivating others
                active_tab = opens[0]
                for t in opens:
                    if t["id"] == active_tab["id"]:
                        if not t.get("is_active"):
                            t["is_active"] = True
                            t["updated_at"] = now
                    else:
                        if t.get("is_active"):
                            t["is_active"] = False
                            t["updated_at"] = now
                session["active_tab_id"] = active_tab["id"]
                changed = True
            else:
                tid = _new_id("tab")
                active_tab = {
                    "id": tid,
                    "session_id": sid,
                    "status": "open",
                    "is_active": True,
                    "current_url": None,
                    "title": None,
                    "history_index": 0,
                    "history": [],
                    "last_visible_text": None,
                    "last_visible_html": None,
                    "created_at": now,
                    "updated_at": now,
                    "closed_at": None
                }
                tabs.append(active_tab)
                session["active_tab_id"] = tid
                changed = True

    # Perform navigation: update tab history, current_url, session current_url
    target = url.strip()
    hist = active_tab.get("history") or []
    idx = active_tab.get("history_index", 0)
    if not isinstance(hist, list):
        hist = []
        idx = 0
    if not isinstance(idx, int) or idx < 0:
        idx = 0

    # Trim forward history if navigating from middle
    if idx < len(hist) - 1:
        hist = hist[: idx + 1]

    hist.append(target)
    idx = len(hist) - 1

    active_tab["history"] = hist
    active_tab["history_index"] = idx
    active_tab["current_url"] = target
    active_tab["updated_at"] = now

    session["current_url"] = target
    session["updated_at"] = now

    # Codegen linkage: if there is an active recording session bound to this session, attach and append action
    codegen_id = None
    recording = None
    for cg in codegen_sessions:
        if cg.get("status") == "recording" and cg.get("session_id") == sid:
            recording = cg
            break
    if recording:
        codegen_id = recording["id"]
        ra = recording.get("recorded_actions")
        if not isinstance(ra, list):
            ra = []
        ra.append({
            "type": "navigate",
            "url": target,
            "tab_id": active_tab.get("id"),
            "ts": now
        })
        recording["recorded_actions"] = ra
        recording["updated_at"] = now

    # Create automation event row
    ev_id = _new_id("ev")
    duration_ms = int((time.time() - t0) * 1000)
    request_params = {
        "url": url,
        "browserType": browserType,
        "width": width,
        "height": height,
        "timeout": timeout,
        "waitUntil": waitUntil,
        "headless": headless
    }
    result = {
        "navigated_url": target,
        "waitUntil": waitUntil or "load",
        "timeout_ms": to_ms if to_ms is not None else session.get("default_timeout_ms"),
        "page": {
            "tab_id": active_tab["id"],
            "current_url": active_tab.get("current_url"),
            "history_index": active_tab.get("history_index"),
            "history_length": len(active_tab.get("history") or [])
        },
        "session": {
            "id": session["id"],
            "browser_type": session.get("browser_type"),
            "headless": session.get("headless"),
            "viewport_width": session.get("viewport_width"),
            "viewport_height": session.get("viewport_height")
        }
    }
    automation_events.append({
        "id": ev_id,
        "session_id": sid,
        "tab_id": active_tab["id"],
        "codegen_session_id": codegen_id,
        "tool_name": "playwright_navigate",
        "status": "succeeded",
        "request_params": request_params,
        "result": result,
        "error": None,
        "duration_ms": duration_ms,
        "created_at": now,
        "updated_at": now
    })

    _save("browser_sessions.json", browser_sessions)
    _save("tabs.json", tabs)
    _save("codegen_sessions.json", codegen_sessions)
    _save("automation_events.json", automation_events)

    return {
        "navigation": {
            "url": target,
            "waitUntil": result["waitUntil"],
            "timeout": result["timeout_ms"]
        },
        "session": result["session"],
        "tab": {
            "id": active_tab["id"],
            "current_url": active_tab.get("current_url"),
            "title": active_tab.get("title"),
            "history_index": active_tab.get("history_index"),
            "history": active_tab.get("history")
        },
        "event_id": ev_id
    }

def playwright_console_logs(type=None, search=None, limit=None, clear=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _event(tool_name, status, request_params, result=None, error=None, session_id=None, tab_id=None, codegen_session_id=None, duration_ms=None):
        ts = _now()
        row = {
            "id": _new_id("ae"),
            "session_id": session_id,
            "tab_id": tab_id,
            "codegen_session_id": codegen_session_id,
            "tool_name": tool_name,
            "status": status,
            "request_params": request_params if request_params is not None else {},
            "result": result,
            "error": error,
            "duration_ms": duration_ms,
            "created_at": ts,
            "updated_at": ts,
        }
        events = _load("automation_events.json")
        events.append(row)
        _save("automation_events.json", events)
        return row

    t0 = time.time()

    allowed_types = ["all", "error", "warning", "log", "info", "debug"]
    if type is not None and (not isinstance(type, str) or type not in allowed_types):
        _event("playwright_console_logs", "failed", {"type": type, "search": search, "limit": limit, "clear": clear},
               error={"message": "Invalid type; must be one of: all, error, warning, log, info, debug"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid type", allowed=allowed_types)

    if search is not None and not isinstance(search, str):
        _event("playwright_console_logs", "failed", {"type": type, "search": search, "limit": limit, "clear": clear},
               error={"message": "search must be a string"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "search must be a string")

    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            _event("playwright_console_logs", "failed", {"type": type, "search": search, "limit": limit, "clear": clear},
                   error={"message": "limit must be a number"},
                   duration_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "limit must be a number")
        if int(limit) <= 0:
            _event("playwright_console_logs", "failed", {"type": type, "search": search, "limit": limit, "clear": clear},
                   error={"message": "limit must be positive"},
                   duration_ms=int((time.time() - t0) * 1000))
            return _err("VALIDATION_ERROR", "limit must be positive")
        limit = int(limit)

    if clear is not None and not isinstance(clear, bool):
        _event("playwright_console_logs", "failed", {"type": type, "search": search, "limit": limit, "clear": clear},
               error={"message": "clear must be a boolean"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "clear must be a boolean")
    if clear is None:
        clear = False

    sessions = _load("browser_sessions.json")
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active:
        # Policy: create implicitly for missing active session (consistent across tools family)
        ts = _now()
        sid = _new_id("bs")
        new_sess = {
            "id": sid,
            "status": "active",
            "browser_type": "chromium",
            "headless": True,
            "viewport_width": 1280,
            "viewport_height": 720,
            "default_timeout_ms": None,
            "user_agent": None,
            "current_url": None,
            "active_tab_id": None,
            "last_error": None,
            "created_at": ts,
            "updated_at": ts,
            "closed_at": None,
        }
        sessions.append(new_sess)
        _save("browser_sessions.json", sessions)
        session = new_sess
    else:
        session = sorted(active, key=lambda r: r.get("created_at") or "")[-1]

    if session.get("status") in ("closing", "closed"):
        _event("playwright_console_logs", "failed", {"type": type, "search": search, "limit": limit, "clear": clear},
               session_id=session.get("id"),
               error={"message": "Session is closed or closing"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Session is closed or closing")

    # Derive "console buffer" from prior persisted events' results (since no separate buffer collection exists).
    # We treat playwright_console_logs retrieval with clear=true as "clear seen-through timestamp" by storing a marker event.
    events = _load("automation_events.json")
    sess_events = [e for e in events if isinstance(e, dict) and e.get("session_id") == session.get("id")]

    # Find last clear marker.
    last_clear_ts = None
    for e in reversed(sorted(sess_events, key=lambda r: r.get("created_at") or "")):
        if e.get("tool_name") == "playwright_console_logs" and isinstance(e.get("request_params"), dict) and e["request_params"].get("clear") is True:
            last_clear_ts = e.get("created_at")
            break

    # Collect console entries from any event.result.console entries after last_clear_ts.
    entries = []
    for e in sess_events:
        c_at = e.get("created_at")
        if last_clear_ts is not None and (c_at is None or c_at <= last_clear_ts):
            continue
        res = e.get("result")
        if isinstance(res, dict) and isinstance(res.get("console"), list):
            for item in res["console"]:
                if isinstance(item, dict):
                    entries.append(item)

    # Apply filters
    def _matches(entry):
        if not isinstance(entry, dict):
            return False
        etype = entry.get("type")
        text = entry.get("text") or ""
        if type not in (None, "all"):
            if etype != type:
                return False
        if search:
            if search not in text:
                return False
        return True

    filtered = [x for x in entries if _matches(x)]

    # Most recent `limit` entries
    if limit is None:
        limit = 100
    filtered = filtered[-limit:]

    # Record retrieval event (always), and if clear=true we rely on this event as marker.
    reqp = {"type": type, "search": search, "limit": limit, "clear": clear}
    retrieval_result = {"entries": filtered, "count": len(filtered)}
    _event("playwright_console_logs", "succeeded", reqp, result=retrieval_result, session_id=session.get("id"),
           tab_id=session.get("active_tab_id"), duration_ms=int((time.time() - t0) * 1000))

    # Update session updated_at (even if clear is false, retrieval touched session)
    for s in sessions:
        if s.get("id") == session.get("id"):
            s["updated_at"] = _now()
            break
    _save("browser_sessions.json", sessions)

    return {"entries": filtered, "count": len(filtered), "session_id": session.get("id")}

def playwright_close(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _event(tool_name, status, request_params, result=None, error=None, session_id=None, tab_id=None, codegen_session_id=None, duration_ms=None):
        ts = _now()
        row = {
            "id": _new_id("ae"),
            "session_id": session_id,
            "tab_id": tab_id,
            "codegen_session_id": codegen_session_id,
            "tool_name": tool_name,
            "status": status,
            "request_params": request_params if request_params is not None else {},
            "result": result,
            "error": error,
            "duration_ms": duration_ms,
            "created_at": ts,
            "updated_at": ts,
        }
        events = _load("automation_events.json")
        events.append(row)
        _save("automation_events.json", events)
        return row

    t0 = time.time()

    sessions = _load("browser_sessions.json")
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active:
        # Closing requires an active session; do not create implicitly here.
        _event("playwright_close", "failed", {}, error={"message": "No active session to close"}, duration_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "No active session to close")

    session = sorted(active, key=lambda r: r.get("created_at") or "")[-1]

    if session.get("status") == "closed":
        _event("playwright_close", "failed", {}, session_id=session.get("id"), error={"message": "Session already closed"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Session already closed")
    if session.get("status") == "closing":
        _event("playwright_close", "failed", {}, session_id=session.get("id"), error={"message": "Session is already closing"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Session is already closing")
    if session.get("status") == "errored":
        # allowed transition errored -> closed (per lifecycle)
        pass
    elif session.get("status") != "active":
        _event("playwright_close", "failed", {}, session_id=session.get("id"),
               error={"message": f"Session in non-closable state: {session.get('status')}"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Session in non-closable state", status=session.get("status"))

    # Transition active -> closing -> closed (enforced)
    ts = _now()
    sid = session.get("id")

    # Update session to closing
    for s in sessions:
        if s.get("id") == sid:
            if s.get("status") == "active":
                s["status"] = "closing"
                s["updated_at"] = ts
            elif s.get("status") == "errored":
                # direct to closed allowed by lifecycle (errored -> closed)
                pass
            break
    _save("browser_sessions.json", sessions)

    # Close all open tabs
    tabs = _load("tabs.json")
    any_tab_mut = False
    for t in tabs:
        if isinstance(t, dict) and t.get("session_id") == sid and t.get("status") in ("open", "closing"):
            # open -> closing -> closed; closing -> closed
            if t.get("status") == "open":
                t["status"] = "closing"
                t["updated_at"] = ts
                any_tab_mut = True
            if t.get("status") == "closing":
                t["status"] = "closed"
                t["closed_at"] = ts
                t["is_active"] = False
                t["updated_at"] = ts
                any_tab_mut = True
    if any_tab_mut:
        _save("tabs.json", tabs)

    # Cancel pending waits for this session (pending/matched -> cancelled)
    waits = _load("network_waits.json")
    any_wait_mut = False
    for w in waits:
        if isinstance(w, dict) and w.get("session_id") == sid and w.get("status") in ("pending", "matched"):
            w["status"] = "cancelled"
            w["updated_at"] = ts
            any_wait_mut = True
    if any_wait_mut:
        _save("network_waits.json", waits)

    # Finalize session to closed (closing -> closed, errored -> closed)
    sessions = _load("browser_sessions.json")
    for s in sessions:
        if s.get("id") == sid:
            if s.get("status") == "active":
                # if some external race, still honor required transition by moving to closing first then closed
                s["status"] = "closing"
                s["updated_at"] = ts
            if s.get("status") == "closing":
                s["status"] = "closed"
                s["closed_at"] = ts
                s["active_tab_id"] = None
                s["updated_at"] = ts
            elif s.get("status") == "errored":
                s["status"] = "closed"
                s["closed_at"] = ts
                s["active_tab_id"] = None
                s["updated_at"] = ts
            elif s.get("status") == "closed":
                # idempotent close after we already closed in this call path
                pass
            else:
                _event("playwright_close", "failed", {}, session_id=sid,
                       error={"message": f"Invalid transition from {s.get('status')} to closed"},
                       duration_ms=int((time.time() - t0) * 1000))
                return _err("INVALID_TRANSITION", "Invalid session state transition", from_status=s.get("status"), to_status="closed")
            session = s
            break
    _save("browser_sessions.json", sessions)

    _event("playwright_close", "succeeded", {}, session_id=sid, result={"status": "closed", "closed_at": session.get("closed_at")},
           duration_ms=int((time.time() - t0) * 1000))

    return {"session_id": sid, "status": "closed", "closed_at": session.get("closed_at")}

def playwright_get(url, **_extra):
    import json, os, datetime, time, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _redact_headers(h):
        out = {}
        if not isinstance(h, dict):
            return out
        for k, v in h.items():
            if not isinstance(k, str):
                continue
            lk = k.lower()
            if lk == "authorization" or lk == "proxy-authorization":
                out[k] = "[REDACTED]"
            else:
                out[k] = v if isinstance(v, str) else str(v)
        return out

    def _event(tool_name, status, request_params, result=None, error=None, session_id=None, tab_id=None, codegen_session_id=None, duration_ms=None):
        ts = _now()
        row = {
            "id": _new_id("ae"),
            "session_id": session_id,
            "tab_id": tab_id,
            "codegen_session_id": codegen_session_id,
            "tool_name": tool_name,
            "status": status,
            "request_params": request_params if request_params is not None else {},
            "result": result,
            "error": error,
            "duration_ms": duration_ms,
            "created_at": ts,
            "updated_at": ts,
        }
        events = _load("automation_events.json")
        events.append(row)
        _save("automation_events.json", events)
        return row

    t0 = time.time()

    if not isinstance(url, str) or not url or not (url.startswith("http://") or url.startswith("https://")):
        _event("playwright_get", "failed", {"url": url}, error={"message": "url must be a non-empty http(s) URL"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "Invalid url")

    # Ensure active session exists (policy: implicitly create if none)
    sessions = _load("browser_sessions.json")
    active = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active:
        ts = _now()
        sid = _new_id("bs")
        new_sess = {
            "id": sid,
            "status": "active",
            "browser_type": "chromium",
            "headless": True,
            "viewport_width": 1280,
            "viewport_height": 720,
            "default_timeout_ms": None,
            "user_agent": None,
            "current_url": None,
            "active_tab_id": None,
            "last_error": None,
            "created_at": ts,
            "updated_at": ts,
            "closed_at": None,
        }
        sessions.append(new_sess)
        _save("browser_sessions.json", sessions)
        session = new_sess
    else:
        session = sorted(active, key=lambda r: r.get("created_at") or "")[-1]

    if session.get("status") in ("closing", "closed"):
        _event("playwright_get", "failed", {"url": url}, session_id=session.get("id"),
               error={"message": "Session is closed or closing"},
               duration_ms=int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Session is closed or closing")

    # Execute HTTP GET
    status = None
    resp_headers = {}
    body_text = ""
    try:
        req = urllib.request.Request(url=url, method="GET", headers={})
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = int(getattr(resp, "status", 200))
            resp_headers = dict(resp.headers.items()) if getattr(resp, "headers", None) is not None else {}
            raw = resp.read()
            # decode best-effort
            try:
                body_text = raw.decode("utf-8")
            except UnicodeDecodeError:
                body_text = raw.decode("latin-1", errors="replace")
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        resp_headers = dict(e.headers.items()) if getattr(e, "headers", None) is not None else {}
        raw = e.read() if hasattr(e, "read") else b""
        try:
            body_text = raw.decode("utf-8")
        except UnicodeDecodeError:
            body_text = raw.decode("latin-1", errors="replace")
    except (urllib.error.URLError, ValueError) as e:
        ev = _event("playwright_get", "failed", {"url": url}, session_id=session.get("id"),
                    error={"message": "Request failed", "detail": str(e)},
                    duration_ms=int((time.time() - t0) * 1000))
        return _err("NOT_FOUND", "Request failed", event_id=ev.get("id"))

    # Persist event (with redaction rules - no token here, but keep structure)
    reqp = {"url": url, "headers": _redact_headers({})}
    # Truncate body for audit determinism/storage
    max_len = 200000
    truncated = False
    if body_text is not None and len(body_text) > max_len:
        body_text_audit = body_text[:max_len]
        truncated = True
    else:
        body_text_audit = body_text

    result = {"status": status, "headers": resp_headers, "body": body_text_audit, "body_truncated": truncated}
    ev = _event("playwright_get", "succeeded" if (status is not None and status < 400) else "failed",
                reqp, result=result if status is not None else None,
                error=None if (status is not None and status < 400) else {"message": f"HTTP error status {status}"},
                session_id=session.get("id"),
                tab_id=session.get("active_tab_id"),
                duration_ms=int((time.time() - t0) * 1000))

    # Map 404 to NOT_FOUND
    if status == 404:
        return _err("NOT_FOUND", "Remote endpoint returned 404", event_id=ev.get("id"), status=status)

    # Other non-2xx: return failed status payload as error (per description)
    if status is None or status < 200 or status >= 300:
        return _err("CONFLICT", f"HTTP request returned status {status}", event_id=ev.get("id"), status=status, headers=resp_headers, body=body_text_audit)

    return {"status": status, "headers": resp_headers, "body": body_text, "event_id": ev.get("id"), "session_id": session.get("id")}

def playwright_post(url, value, token=None, headers=None, **_extra):
    import json, os, datetime, time, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:24]}".lower()

    def _redact_headers(h):
        redacted_keys = {"authorization", "proxy-authorization", "x-api-key", "api-key"}
        if not isinstance(h, dict):
            return {}
        out = {}
        for k, v in h.items():
            if not isinstance(k, str):
                continue
            lk = k.lower()
            if lk in redacted_keys:
                out[k] = "[REDACTED]"
            else:
                out[k] = v if isinstance(v, str) else str(v)
        return out

    def _log(tool_status, request_params, result=None, error=None, session_id=None, tab_id=None, codegen_session_id=None):
        events = _load("automation_events.json")
        ts = _now()
        row = {
            "id": _new_id("pws_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "codegen_session_id": codegen_session_id,
            "tool_name": "playwright_post",
            "status": tool_status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "result": result,
            "error": error,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": ts,
            "updated_at": ts,
        }
        events.append(row)
        _save("automation_events.json", events)
        return row

    t0 = time.time()

    if not isinstance(url, str) or not url.strip():
        _log("failed", {"url": url, "value": value, "token": "[REDACTED]" if token else None, "headers": _redact_headers(headers or {})}, error={"message": "url must be a non-empty string"})
        return _err("VALIDATION_ERROR", "url must be a non-empty string", field="url")
    if not (url.strip().startswith("http://") or url.strip().startswith("https://")):
        _log("failed", {"url": url, "value": value, "token": "[REDACTED]" if token else None, "headers": _redact_headers(headers or {})}, error={"message": "url must start with http:// or https://"})
        return _err("VALIDATION_ERROR", "url must start with http:// or https://", field="url")
    if not isinstance(value, str) or value == "":
        _log("failed", {"url": url.strip(), "value": value, "token": "[REDACTED]" if token else None, "headers": _redact_headers(headers or {})}, error={"message": "value must be a non-empty string"})
        return _err("VALIDATION_ERROR", "value must be a non-empty string", field="value")
    if token is not None and not isinstance(token, str):
        _log("failed", {"url": url.strip(), "value": value, "token": None, "headers": _redact_headers(headers or {})}, error={"message": "token must be a string when provided"})
        return _err("VALIDATION_ERROR", "token must be a string when provided", field="token")
    if headers is not None and not isinstance(headers, dict):
        _log("failed", {"url": url.strip(), "value": value, "token": "[REDACTED]" if token else None, "headers": {}}, error={"message": "headers must be an object when provided"})
        return _err("VALIDATION_ERROR", "headers must be an object when provided", field="headers")
    if isinstance(headers, dict):
        for k, v in headers.items():
            if not isinstance(k, str) or not isinstance(v, str):
                _log("failed", {"url": url.strip(), "value": value, "token": "[REDACTED]" if token else None, "headers": _redact_headers(headers)}, error={"message": "headers values must be strings"})
                return _err("VALIDATION_ERROR", "headers values must be strings", field="headers")

    u = url.strip()

    sessions = _load("browser_sessions.json")
    codegens = _load("codegen_sessions.json")

    # Bind to an active session if exists; otherwise session_id can be null (schema allows nullable for HTTP tools)
    active_session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active":
            active_session = s
            break
    session_id = active_session.get("id") if active_session else None

    codegen_session_id = None
    if session_id:
        for cg in codegens:
            if isinstance(cg, dict) and cg.get("status") == "recording" and cg.get("session_id") == session_id:
                codegen_session_id = cg.get("id")
                break

    # Prepare request headers
    req_headers = {}
    if isinstance(headers, dict):
        req_headers.update(headers)
    if token:
        req_headers["Authorization"] = f"Bearer {token}"

    persisted_params = {
        "url": u,
        "value": value,
        "token": "[REDACTED]" if token else None,
        "headers": _redact_headers(req_headers),
    }

    status_code = None
    resp_headers = {}
    resp_body = ""
    error_obj = None

    try:
        data = value.encode("utf-8")
        req = urllib.request.Request(u, data=data, method="POST")
        for k, v in req_headers.items():
            # urllib requires str header values
            if isinstance(k, str) and isinstance(v, str):
                req.add_header(k, v)
        if "Content-Type" not in {k.title(): v for k, v in req_headers.items() if isinstance(k, str)}:
            req.add_header("Content-Type", "text/plain; charset=utf-8")

        with urllib.request.urlopen(req, timeout=30) as resp:
            status_code = getattr(resp, "status", None) or resp.getcode()
            resp_headers = dict(resp.headers.items()) if resp.headers else {}
            raw = resp.read()
            try:
                resp_body = raw.decode("utf-8", errors="replace")
            except Exception:
                resp_body = str(raw)
    except urllib.error.HTTPError as e:
        status_code = e.code
        resp_headers = dict(e.headers.items()) if e.headers else {}
        raw = e.read() if hasattr(e, "read") else b""
        try:
            resp_body = raw.decode("utf-8", errors="replace")
        except Exception:
            resp_body = str(raw)
        error_obj = {"message": f"HTTPError {e.code}"}
    except urllib.error.URLError as e:
        error_obj = {"message": f"Transport error: {getattr(e, 'reason', str(e))}"}
    except ValueError as e:
        error_obj = {"message": f"Invalid URL: {str(e)}"}

    # Determine API outcome rules
    if error_obj is not None and status_code is None:
        _log("failed", persisted_params, error=error_obj, session_id=session_id, codegen_session_id=codegen_session_id)
        return _err("CONFLICT", "Transport failure", detail=error_obj.get("message"))

    if status_code == 404:
        result = {"status": status_code, "headers": resp_headers, "body": resp_body}
        _log("failed", persisted_params, result=result, error={"message": "Remote returned 404"}, session_id=session_id, codegen_session_id=codegen_session_id)
        return _err("NOT_FOUND", "Remote returned 404", url=u)

    # Success (even for other 4xx/5xx, we return captured response; log as failed if >=400)
    result = {"status": status_code, "headers": resp_headers, "body": resp_body}
    if status_code is not None and status_code >= 400:
        _log("failed", persisted_params, result=result, error={"message": f"Remote returned HTTP {status_code}"}, session_id=session_id, codegen_session_id=codegen_session_id)
    else:
        _log("succeeded", persisted_params, result=result, session_id=session_id, codegen_session_id=codegen_session_id)
    return {"response": result}

