def playwright_drag(sourceSelector, targetSelector, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(sourceSelector, str) or sourceSelector.strip() == "":
        return _err("VALIDATION_ERROR", "sourceSelector must be a non-empty string.")
    if not isinstance(targetSelector, str) or targetSelector.strip() == "":
        return _err("VALIDATION_ERROR", "targetSelector must be a non-empty string.")

    sessions = _load("browser_sessions.json")
    tabs = _load("tabs.json")
    codegens = _load("codegen_sessions.json")
    events = _load("automation_events.json")

    # Active session policy: create if none
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if not active_sessions:
        sid = "sess_" + uuid.uuid4().hex
        sess = {
            "id": sid,
            "status": "active",
            "browser_type": "chromium",
            "headless": True,
            "viewport_width": 1280,
            "viewport_height": 720,
            "default_timeout_ms": None,
            "user_agent": None,
            "current_url": None,
            "active_tab_id": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
            "closed_at": None,
        }
        sessions.append(sess)
        active_sessions = [sess]
        _save("browser_sessions.json", sessions)

    session = active_sessions[0]
    session_id = session.get("id")

    active_tab_id = session.get("active_tab_id")
    tab = None
    if isinstance(active_tab_id, str) and active_tab_id:
        for t in tabs:
            if isinstance(t, dict) and t.get("id") == active_tab_id and t.get("session_id") == session_id:
                tab = t
                break
    if tab is None:
        for t in tabs:
            if isinstance(t, dict) and t.get("session_id") == session_id and t.get("is_active") is True:
                tab = t
                active_tab_id = t.get("id")
                session["active_tab_id"] = active_tab_id
                session["updated_at"] = now
                _save("browser_sessions.json", sessions)
                break

    def _log_event(status, result=None, error=None, duration_ms=None):
        eid = "evt_" + uuid.uuid4().hex
        req = {"sourceSelector": sourceSelector, "targetSelector": targetSelector}
        row = {
            "id": eid,
            "session_id": session_id,
            "tab_id": active_tab_id if isinstance(active_tab_id, str) else None,
            "codegen_session_id": None,
            "tool_name": "playwright_drag",
            "status": status,
            "request_params": req,
            "result": result,
            "error": error,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        cg = None
        for c in codegens:
            if isinstance(c, dict) and c.get("status") == "recording" and c.get("session_id") == session_id:
                cg = c
                break
        if cg is not None:
            row["codegen_session_id"] = cg.get("id")
        events.append(row)
        _save("automation_events.json", events)

        if cg is not None:
            ra = cg.get("recorded_actions")
            if not isinstance(ra, list):
                ra = []
            ra.append({
                "tool": "playwright_drag",
                "tab_id": row["tab_id"],
                "source": sourceSelector,
                "target": targetSelector,
                "ts": now
            })
            cg["recorded_actions"] = ra
            cg["updated_at"] = now
            _save("codegen_sessions.json", codegens)
        return eid

    if session.get("status") != "active":
        dur = int((time.time() - start) * 1000)
        _log_event("failed", error={"message": "Session is not active."}, duration_ms=dur)
        return _err("INVALID_TRANSITION", "Session is not active.", status=session.get("status"))

    if tab is None:
        dur = int((time.time() - start) * 1000)
        _log_event("failed", error={"message": "No active page/tab."}, duration_ms=dur)
        return _err("NOT_FOUND", "No active page/tab.")

    if tab.get("status") != "open":
        dur = int((time.time() - start) * 1000)
        _log_event("failed", error={"message": "Tab is not open."}, duration_ms=dur)
        return _err("CONFLICT", "Page/tab is closed or not interactable.", tab_status=tab.get("status"))

    # Offline deterministic behavior: we cannot locate DOM elements.
    # Enforce "NOT_FOUND if source or target cannot be located" deterministically:
    # consider selectors containing ':notfound' as missing, and ':disabled' as non-interactable.
    def _missing(sel):
        return ":notfound" in sel or sel.strip() in ("#missing", ".missing")
    def _non_interactable(sel):
        return ":disabled" in sel or ":hidden" in sel or ":detached" in sel or ":covered" in sel

    if _missing(sourceSelector) or _missing(targetSelector):
        dur = int((time.time() - start) * 1000)
        _log_event("failed", error={"message": "Source or target element not found."}, duration_ms=dur)
        return _err("NOT_FOUND", "Source or target element cannot be located.")

    if _non_interactable(sourceSelector) or _non_interactable(targetSelector):
        dur = int((time.time() - start) * 1000)
        _log_event("failed", error={"message": "Source or target is not interactable."}, duration_ms=dur)
        return _err("CONFLICT", "Elements are not interactable.")

    # Success: no DOM state change; just record the action.
    session["updated_at"] = now
    tab["updated_at"] = now
    _save("browser_sessions.json", sessions)
    _save("tabs.json", tabs)

    result = {"ok": True, "session_id": session_id, "tab_id": tab.get("id")}
    dur = int((time.time() - start) * 1000)
    _log_event("succeeded", result=result, error=None, duration_ms=dur)
    return result

