    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:24]}".lower()

    def _log(tool_status, request_params, result=None, error=None, session_id=None, tab_id=None, codegen_session_id=None, event_id=None):
        events = _load("automation_events.json")
        ts = _now()
        row = {
            "id": event_id or _new_id("pws_evt"),
            "session_id": session_id,
            "tab_id": tab_id,
            "codegen_session_id": codegen_session_id,
            "tool_name": "playwright_save_as_pdf",
            "status": tool_status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "result": result,
            "error": error,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": ts,
            "updated_at": ts,
        }
        events.append(row)
        _save("automation_events.json", events)
        return row

    # Validate inputs
    req = {"outputPath": outputPath, "filename": filename, "format": format, "printBackground": printBackground, "margin": margin}

    if not isinstance(outputPath, str) or not outputPath.strip():
        _log("failed", req, error={"message": "outputPath must be a non-empty string"})
        return _err("VALIDATION_ERROR", "outputPath must be a non-empty string", field="outputPath")
    outputPath = outputPath.strip()
    if not outputPath.startswith("/"):
        _log("failed", req, error={"message": "outputPath must be an absolute path (start with '/')"})
        return _err("VALIDATION_ERROR", "outputPath must be an absolute path (start with '/')", field="outputPath")

    if filename is None:
        filename = "page.pdf"
    else:
        if not isinstance(filename, str) or not filename.strip():
            _log("failed", req, error={"message": "filename must be a non-empty string when provided"})
            return _err("VALIDATION_ERROR", "filename must be a non-empty string when provided", field="filename")
        filename = filename.strip()
        if "/" in filename or "\\" in filename:
            _log("failed", req, error={"message": "filename must not contain path separators"})
            return _err("VALIDATION_ERROR", "filename must not contain path separators", field="filename")
        if not filename.lower().endswith(".pdf"):
            filename = filename + ".pdf"

    if format is not None and not isinstance(format, str):
        _log("failed", req, error={"message": "format must be a string when provided"})
        return _err("VALIDATION_ERROR", "format must be a string when provided", field="format")
    if printBackground is not None and not isinstance(printBackground, bool):
        _log("failed", req, error={"message": "printBackground must be a boolean when provided"})
        return _err("VALIDATION_ERROR", "printBackground must be a boolean when provided", field="printBackground")

    # margin: {top/right/bottom/left} strings like "1in" / "10px" / "2cm" / "0"
    if margin is not None:
        if not isinstance(margin, dict):
            _log("failed", req, error={"message": "margin must be an object when provided"})
            return _err("VALIDATION_ERROR", "margin must be an object when provided", field="margin")
        for k in ("top", "right", "bottom", "left"):
            if k in margin and margin[k] is not None:
                if not isinstance(margin[k], str):
                    _log("failed", req, error={"message": f"margin.{k} must be a string"})
                    return _err("VALIDATION_ERROR", f"margin.{k} must be a string", field=f"margin.{k}")
                v = margin[k].strip()
                # Accept CSS-ish length tokens: number with optional unit, or "0"
                if v != "0" and not re.match(r"^[0-9]+(\.[0-9]+)?(px|in|cm|mm)$", v):
                    _log("failed", req, error={"message": f"margin.{k} must be a CSS length like '10px', '1in', '2cm', '0'"})
                    return _err("VALIDATION_ERROR", f"margin.{k} must be a CSS length like '10px', '1in', '2cm', '0'", field=f"margin.{k}")

    sessions = _load("browser_sessions.json")
    tabs = _load("tabs.json")
    codegens = _load("codegen_sessions.json")
    events = _load("automation_events.json")
    artifacts = _load("artifacts.json")

    # Policy: must operate on exactly one active session; if none exists, create implicitly.
    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active"]
    if len(active_sessions) == 1:
        sess = active_sessions[0]
    elif len(active_sessions) == 0:
        ts = _now()
        sess = {
            "id": _new_id("pws_sess"),
            "status": "active",
            "browser_type": "chromium",
            "headless": True,
            "viewport_width": 1280,
            "viewport_height": 720,
            "default_timeout_ms": None,
            "user_agent": None,
            "current_url": None,
            "active_tab_id": None,
            "last_error": None,
            "created_at": ts,
            "updated_at": ts,
            "closed_at": None,
        }
        sessions.append(sess)
        _save("browser_sessions.json", sessions)
    else:
        # Deterministic: pick most recently updated
        def _ts(row):
            return row.get("updated_at") or row.get("created_at") or ""
        sess = sorted(active_sessions, key=_ts, reverse=True)[0]

    session_id = sess.get("id")

    # Must have an active/open tab (page)
    active_tab = None
    if sess.get("active_tab_id"):
        for t in tabs:
            if isinstance(t, dict) and t.get("id") == sess.get("active_tab_id") and t.get("session_id") == session_id:
                active_tab = t
                break
    if active_tab is None:
        for t in tabs:
            if isinstance(t, dict) and t.get("session_id") == session_id and t.get("status") == "open" and t.get("is_active") is True:
                active_tab = t
                break

    if active_tab is None:
        _log("failed", req, error={"message": "No active page/tab", "session_id": session_id}, session_id=session_id)
        return _err("NOT_FOUND", "No active page/tab", session_id=session_id)

    if active_tab.get("status") != "open":
        _log("failed", req, error={"message": "Page/tab is closed", "tab_id": active_tab.get("id"), "status": active_tab.get("status")}, session_id=session_id, tab_id=active_tab.get("id"))
        return _err("CONFLICT", "Page/tab is closed", tab_id=active_tab.get("id"), status=active_tab.get("status"))

    tab_id = active_tab.get("id")

    # Link to recording codegen session bound to this browser session (if any)
    codegen_session_id = None
    for cg in codegens:
        if isinstance(cg, dict) and cg.get("status") == "recording" and cg.get("session_id") == session_id:
            codegen_session_id = cg.get("id")
            break

    # Create automation event first
    event_id = _new_id("pws_evt")
    ts = _now()
    event_row = {
        "id": event_id,
        "session_id": session_id,
        "tab_id": tab_id,
        "codegen_session_id": codegen_session_id,
        "tool_name": "playwright_save_as_pdf",
        "status": "succeeded",
        "request_params": {"outputPath": outputPath, "filename": filename, "format": format, "printBackground": printBackground, "margin": margin},
        "result": None,
        "error": None,
        "duration_ms": max(0, int((time.time() - t0) * 1000)),
        "created_at": ts,
        "updated_at": ts,
    }
    events.append(event_row)
    _save("automation_events.json", events)

    # Create artifact row (file_path under outputPath)
    file_path = outputPath.rstrip("/") + "/" + filename
    metadata = {
        "format": format,
        "printBackground": printBackground,
        "margin": margin,
        "outputPath": outputPath,
        "filename": filename,
    }

    artifact_row = {
        "id": _new_id("pws_art"),
        "session_id": session_id,
        "tab_id": tab_id,
        "event_id": event_id,
        "codegen_session_id": codegen_session_id,
        "kind": "pdf",
        "name": filename,
        "content_type": "application/pdf",
        "storage_mode": "file_path",
        "base64_data": None,
        "file_path": file_path,
        "byte_size": None,
        "metadata": metadata if isinstance(metadata, dict) else {},
        "created_at": ts,
        "updated_at": ts,
    }
    artifacts.append(artifact_row)
    _save("artifacts.json", artifacts)

    # Update event result to reference artifact (persisted update)
    # (Update the last appended row for determinism)
    events = _load("automation_events.json")
    for i in range(len(events) - 1, -1, -1):
        r = events[i]
        if isinstance(r, dict) and r.get("id") == event_id:
            r2 = dict(r)
            r2["result"] = {"artifact_id": artifact_row.get("id"), "file_path": file_path, "filename": filename, "content_type": "application/pdf"}
            r2["updated_at"] = _now()
            events[i] = r2
            _save("automation_events.json", events)
            break

    result = {
        "artifact": artifact_row,
        "event_id": event_id,
    }
    return result

def list_browser_sessions(status=None, browserType=None, createdAfter=None, createdBefore=None, page=None, pageSize=None, includeClosedTabs=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:24]}".lower()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "BAD"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return "BAD"

    def _to_dt(created_at):
        if not isinstance(created_at, str):
            return None
        ca = _parse_rfc3339(created_at)
        if ca == "BAD":
            return None
        return ca

    t0 = time.time()
    now = _now()

    allowed_status = {"active", "closing", "closed", "errored"}
    allowed_bt = {"chromium", "firefox", "webkit"}

    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            # still log call
            events = _load("automation_events.json")
            events.append({
                "id": _new_id("pws_evt"),
                "session_id": None,
                "tab_id": None,
                "codegen_session_id": None,
                "tool_name": "list_browser_sessions",
                "status": "failed",
                "request_params": {"status": status, "browserType": browserType, "createdAfter": createdAfter, "createdBefore": createdBefore, "page": page, "pageSize": pageSize, "includeClosedTabs": includeClosedTabs},
                "result": None,
                "error": {"message": "Invalid status filter"},
                "duration_ms": int((time.time() - t0) * 1000),
                "created_at": now,
                "updated_at": now,
            })
            _save("automation_events.json", events)
            return _err("VALIDATION_ERROR", "Invalid status filter", field="status")

    if browserType is not None:
        if not isinstance(browserType, str) or browserType not in allowed_bt:
            events = _load("automation_events.json")
            events.append({
                "id": _new_id("pws_evt"),
                "session_id": None,
                "tab_id": None,
                "codegen_session_id": None,
                "tool_name": "list_browser_sessions",
                "status": "failed",
                "request_params": {"status": status, "browserType": browserType, "createdAfter": createdAfter, "createdBefore": createdBefore, "page": page, "pageSize": pageSize, "includeClosedTabs": includeClosedTabs},
                "result": None,
                "error": {"message": "Invalid browserType filter"},
                "duration_ms": int((time.time() - t0) * 1000),
                "created_at": now,
                "updated_at": now,
            })
            _save("automation_events.json", events)
            return _err("VALIDATION_ERROR", "Invalid browserType filter", field="browserType")

    ca = _parse_rfc3339(createdAfter)
    cb = _parse_rfc3339(createdBefore)
    # Relax createdAfter/createdBefore parsing: if not RFC3339, treat as no filter instead of error
    if ca == "BAD":
        ca = None
    if cb == "BAD":
        cb = None

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50
    if includeClosedTabs is None:
        includeClosedTabs = False

    if not (isinstance(page, (int, float)) and int(page) == page and page >= 1):
        return _err("VALIDATION_ERROR", "page must be a 1-based integer", field="page")
    page = int(page)

    if not (isinstance(pageSize, (int, float)) and int(pageSize) == pageSize and 1 <= int(pageSize) <= 200):
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200", field="pageSize")
    pageSize = int(pageSize)

    if not isinstance(includeClosedTabs, bool):
        return _err("VALIDATION_ERROR", "includeClosedTabs must be a boolean", field="includeClosedTabs")

    sessions = _load("browser_sessions.json")
    tabs = _load("tabs.json")

    filtered = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if browserType is not None and s.get("browser_type") != browserType:
            continue
        sdt = _to_dt(s.get("created_at"))
        if ca is not None and sdt is not None and sdt <= ca:
            continue
        if cb is not None and sdt is not None and sdt >= cb:
            continue
        filtered.append(s)

    # sort created_at desc (unknown created_at last)
    def _sort_key(s):
        dt = _to_dt(s.get("created_at"))
        if dt is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    start = (page - 1) * pageSize
    end = start + pageSize
    page_rows = filtered[start:end]
    has_more = end < total

    # attach closed tab counts if requested
    if includeClosedTabs:
        # precompute per session counts
        counts = {}
        for t in tabs:
            if not isinstance(t, dict):
                continue
            sid = t.get("session_id")
            if not sid:
                continue
            c = counts.setdefault(sid, {"open": 0, "closing": 0, "closed": 0, "total": 0})
            st = t.get("status")
            if st in ("open", "closing", "closed"):
                c[st] += 1
            c["total"] += 1
        out_rows = []
        for s in page_rows:
            ss = dict(s)
            ss["tabs_summary"] = counts.get(s.get("id"), {"open": 0, "closing": 0, "closed": 0, "total": 0})
            out_rows.append(ss)
        page_rows = out_rows

    # log read call (observable dynamics)
    events = _load("automation_events.json")
    events.append({
        "id": _new_id("pws_evt"),
        "session_id": None,
        "tab_id": None,
        "codegen_session_id": None,
        "tool_name": "list_browser_sessions",
        "status": "succeeded",
        "request_params": {"status": status, "browserType": browserType, "createdAfter": createdAfter, "createdBefore": createdBefore, "page": page, "pageSize": pageSize, "includeClosedTabs": includeClosedTabs},
        "result": {"count": len(page_rows), "total": total},
        "error": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "created_at": now,
        "updated_at": now,
    })
    _save("automation_events.json", events)

    return {
        "sessions": page_rows,
        "page": page,
        "page_size": pageSize,
        "total": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
    }

def list_automation_events(sessionId=None, tabId=None, codegenSessionId=None, toolName=None, status=None, since=None, until=None, page=None, pageSize=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate pagination
    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50

    if isinstance(page, bool) or not isinstance(page, (int, float)) or int(page) != page or page < 1:
        return _err("VALIDATION_ERROR", "page must be a 1-based integer")
    if isinstance(pageSize, bool) or not isinstance(pageSize, (int, float)) or int(pageSize) != pageSize or pageSize < 1 or pageSize > 500:
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 500")
    page = int(page)
    pageSize = int(pageSize)

    # Validate filters types
    for nm, v in [("sessionId", sessionId), ("tabId", tabId), ("codegenSessionId", codegenSessionId), ("toolName", toolName)]:
        if v is not None and (not isinstance(v, str) or not v.strip()):
            return _err("VALIDATION_ERROR", f"{nm} must be a non-empty string when provided")

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("success", "error", "timeout", "cancelled"):
            return _err("VALIDATION_ERROR", "status must be one of: success, error, timeout, cancelled")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string")
        try:
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp string")

    since_dt = _parse_rfc3339(since, "since")
    if isinstance(since_dt, dict) and "error" in since_dt:
        return since_dt
    until_dt = _parse_rfc3339(until, "until")
    if isinstance(until_dt, dict) and "error" in until_dt:
        return until_dt

    # Read events
    events = _load("automation_events.json")

    # Map vendor status filter -> stored enum (succeeded/failed). Other statuses can't exist in this datastore.
    status_map = {"success": "succeeded", "error": "failed", "timeout": None, "cancelled": None}
    desired_stored_status = status_map.get(status) if status is not None else None
    if status in ("timeout", "cancelled"):
        # Deterministically return empty set (no such statuses are persisted in this schema)
        filtered = []
    else:
        filtered = []
        for ev in events:
            if sessionId is not None and ev.get("session_id") != sessionId:
                continue
            if tabId is not None and ev.get("tab_id") != tabId:
                continue
            if codegenSessionId is not None and ev.get("codegen_session_id") != codegenSessionId:
                continue
            if toolName is not None and ev.get("tool_name") != toolName:
                continue
            if desired_stored_status is not None and ev.get("status") != desired_stored_status:
                continue

            if since_dt is not None or until_dt is not None:
                ca = ev.get("created_at")
                if isinstance(ca, str) and ca:
                    try:
                        x = ca
                        if x.endswith("Z"):
                            x = x[:-1] + "+00:00"
                        ev_dt = datetime.datetime.fromisoformat(x)
                        if ev_dt.tzinfo is None:
                            ev_dt = ev_dt.replace(tzinfo=datetime.timezone.utc)
                        ev_dt = ev_dt.astimezone(datetime.timezone.utc)
                    except Exception:
                        ev_dt = None
                else:
                    ev_dt = None

                if since_dt is not None and ev_dt is not None and ev_dt < since_dt:
                    continue
                if until_dt is not None and ev_dt is not None and ev_dt >= until_dt:
                    continue
                # If ev_dt is None, do not exclude (best-effort).

            filtered.append(ev)

    # Sort newest first by created_at then id
    def _sort_key(ev):
        ca = ev.get("created_at")
        try:
            x = ca
            if isinstance(x, str) and x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x) if isinstance(x, str) else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            ts = dt.timestamp()
        except Exception:
            ts = 0.0
        return (-ts, str(ev.get("id") or ""))
    filtered.sort(key=_sort_key)

    total = len(filtered)
    start = (page - 1) * pageSize
    end = start + pageSize
    page_items = filtered[start:end]
    has_more = end < total

    # Audit this read as an automation event as well (service dynamics)
    ev_id = "ae_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    duration_ms = max(0, int((time.time() - t0) * 1000))
    events.append({
        "id": ev_id,
        "session_id": sessionId,
        "tab_id": tabId,
        "codegen_session_id": codegenSessionId,
        "tool_name": "list_automation_events",
        "status": "succeeded",
        "request_params": {
            "sessionId": sessionId,
            "tabId": tabId,
            "codegenSessionId": codegenSessionId,
            "toolName": toolName,
            "status": status,
            "since": since,
            "until": until,
            "page": page,
            "pageSize": pageSize
        },
        "result": {"returned": len(page_items), "total": total},
        "error": None,
        "duration_ms": duration_ms,
        "created_at": now,
        "updated_at": now
    })
    _save("automation_events.json", events)

    return {
        "events": page_items,
        "meta": {
            "page": page,
            "page_size": pageSize,
            "total": total,
            "has_more": has_more
        }
    }

def list_artifacts(sessionId=None, tabId=None, eventId=None, codegenSessionId=None, kind=None, name=None, includeData=None, page=None, pageSize=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0162000" if __import__("os").path.isdir("./environment_mix/0162000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Defaults
    if includeData is None:
        includeData = False
    if not isinstance(includeData, bool):
        return _err("VALIDATION_ERROR", "includeData must be a boolean")

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50

    if isinstance(page, bool) or not isinstance(page, (int, float)) or int(page) != page or page < 1:
        return _err("VALIDATION_ERROR", "page must be a 1-based integer")
    if isinstance(pageSize, bool) or not isinstance(pageSize, (int, float)) or int(pageSize) != pageSize or pageSize < 1 or pageSize > 200:
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200")
    page = int(page)
    pageSize = int(pageSize)

    for nm, v in [("sessionId", sessionId), ("tabId", tabId), ("eventId", eventId), ("codegenSessionId", codegenSessionId)]:
        if v is not None and (not isinstance(v, str) or not v.strip()):
            return _err("VALIDATION_ERROR", f"{nm} must be a non-empty string when provided")

    if kind is not None:
        if not isinstance(kind, str):
            return _err("VALIDATION_ERROR", "kind must be a string")
        if kind not in ("screenshot", "pdf", "test_output", "other"):
            return _err("VALIDATION_ERROR", "kind must be one of: screenshot, pdf, test_output, other")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")

    artifacts = _load("artifacts.json")
    events = _load("automation_events.json")

    # Map external kinds to stored kinds (schema supports: screenshot, pdf, generated_test)
    def _kind_match(row_kind, requested):
        if requested is None:
            return True
        if requested in ("screenshot", "pdf"):
            return row_kind == requested
        if requested == "test_output":
            return row_kind == "generated_test"
        if requested == "other":
            return row_kind not in ("screenshot", "pdf", "generated_test")
        return False

    filtered = []
    nm_sub = name.lower() if isinstance(name, str) else None
    for a in artifacts:
        if sessionId is not None and a.get("session_id") != sessionId:
            continue
        if tabId is not None and a.get("tab_id") != tabId:
            continue
        if eventId is not None and a.get("event_id") != eventId:
            continue
        if codegenSessionId is not None and a.get("codegen_session_id") != codegenSessionId:
            continue
        if not _kind_match(a.get("kind"), kind):
            continue
        if nm_sub is not None:
            an = a.get("name") or ""
            if nm_sub not in an.lower():
                continue
        filtered.append(a)

    # Sort newest first by created_at then id
    def _sort_key(a):
        ca = a.get("created_at")
        try:
            x = ca
            if isinstance(x, str) and x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x) if isinstance(x, str) else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            ts = dt.timestamp()
        except Exception:
            ts = 0.0
        return (-ts, str(a.get("id") or ""))
    filtered.sort(key=_sort_key)

    total = len(filtered)
    start = (page - 1) * pageSize
    end = start + pageSize
    page_items = filtered[start:end]
    has_more = end < total

    # Conditionally strip base64_data
    out_items = []
    for a in page_items:
        aa = dict(a)
        if aa.get("storage_mode") == "base64_inline":
            if not includeData:
                aa.pop("base64_data", None)
        else:
            aa.pop("base64_data", None)
        out_items.append(aa)

    # Audit read
    ev_id = "ae_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    duration_ms = max(0, int((time.time() - t0) * 1000))
    events.append({
        "id": ev_id,
        "session_id": sessionId,
        "tab_id": tabId,
        "codegen_session_id": codegenSessionId,
        "tool_name": "list_artifacts",
        "status": "succeeded",
        "request_params": {
            "sessionId": sessionId,
            "tabId": tabId,
            "eventId": eventId,
            "codegenSessionId": codegenSessionId,
            "kind": kind,
            "name": name,
            "includeData": includeData,
            "page": page,
            "pageSize": pageSize
        },
        "result": {"returned": len(out_items), "total": total},
        "error": None,
        "duration_ms": duration_ms,
        "created_at": now,
        "updated_at": now
    })
    _save("automation_events.json", events)

    return {
        "artifacts": out_items,
        "meta": {
            "page": page,
            "page_size": pageSize,
            "total": total,
            "has_more": has_more
        }
    }
